-- private

function LadderCompetionDanAnimDialog:UpdateViewInfo_()
    KTool.SetActive(self.ImgTxt, self.segmentRiseStatus_ > 0)
    KTool.SetActive(self.TxtState1, self.segmentRiseStatus_ ~= 0)
    KTool.SetActive(self.TxtState2, self.segmentRiseStatus_ ~= 0)

    if self.segmentRiseStatus_ > 0 then
        CfUtils.FillText(self.TxtState1.transform:Find('TxtState'), localize('提升'))
        CfUtils.FillText(self.TxtState2.transform:Find('TxtState'), localize('提升'))
        CfUtils.SetUISwitchText(self.TxtState1.transform:Find('TxtEnglishState'), 1)
        CfUtils.SetUISwitchText(self.TxtState2.transform:Find('TxtEnglishState'), 1)
    else
        CfUtils.FillText(self.TxtState1.transform:Find('TxtState'), localize('变化'))
        CfUtils.FillText(self.TxtState2.transform:Find('TxtState'), localize('变化'))
        CfUtils.SetUISwitchText(self.TxtState1.transform:Find('TxtEnglishState'), 2)
        CfUtils.SetUISwitchText(self.TxtState2.transform:Find('TxtEnglishState'), 2)
    end
    local ladderCompetionUtils = import("Game.UI.LadderCompetion.LadderCompetionUtils")
    ---@type LadderGradeVo
    local oldLadderGradeVo  = ladderCompetionUtils.GetGradeVo(self.oldSegmentId_, self.oldSubSegmentId_)
    ---@type LadderGradeVo
    local newLadderGradeVo  = ladderCompetionUtils.GetGradeVo(self.newSegmentId_, self.newSubSegmentId_)

    local starCount = self.oldSubSegmentId_
    for i = 1, 5 do
        local child = self.StarGroup.transform:GetChild(i - 1)
        KTool.SetActive(child, i <= starCount)
    end
    
    local oldSegmentIcon = oldLadderGradeVo.icon
    local newSegmentIcon = newLadderGradeVo.icon
    CfUtils.FillImage(self.ImgPositionOld, oldSegmentIcon)
    CfUtils.FillImage(self.ImgPositionOld2, oldSegmentIcon)
    CfUtils.FillImage(self.ImgPositionOld3, oldSegmentIcon)
    CfUtils.FillImage(self.ImgPositionNew, newSegmentIcon)
    CfUtils.FillImage(self.ImgPositionNew2, newSegmentIcon)
    CfUtils.FillImage(self.ImgPositionNew3, newSegmentIcon)

    CfUtils.SetUISwitchParticleSystem(self.UIFX_RiseRect3, self.newSegmentId_)
    CfUtils.SetUISwitchParticleSystem(self.UIFX_RiseRect4, self.newSegmentId_)
end


---@param finishCB fun():void
function LadderCompetionDanAnimDialog:DoSegmentAnimAction_(finishCB)
    if self.animActionCo_ ~= nil then
        cs_coroutine.stop(self.animActionCo_)
    end
    self.animActionCo_ = cs_coroutine.start(function()

        --- append blocker
        UIRaycastBlocker:AddCondition(ANIM_ACTION_BLOCKER_NAME)

        -- tween move
        -- 升星动画 0.05s
        local lastAnimTime = 0
        if self.segmentRiseStatus_ == 0 then --无段位变化状态
            if self.starRiseStatus_ > 0 then    --升星
                CfUtils.PlayAnimation(self.Root,"LadderCompetionDanAnimRiseStar")
                local idleStarCount = self.oldSubSegmentId_
                local starCount = self.newSubSegmentId_
                for i = 1, starCount do
                    local child = self.StarGroup.transform:GetChild(i - 1)
                    if i <= idleStarCount then
                        CfUtils.PlayAnimation(child.gameObject, "LadderCompetionDanAnimStarDefault")
                    else
                        KTool.SetActive(child.gameObject,true)
                        CfUtils.PlayAnimation(child.gameObject,"LadderCompetionDanAnimStarRise")
                        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.05))
                    end
                end
                lastAnimTime = CfUtils.GetAnimationTime(self.Root,"LadderCompetionDanAnimRiseStar")
            elseif self.starRiseStatus_ < 0 then    --降星
                CfUtils.PlayAnimation(self.Root,"LadderCompetionDanAnimDropStar")
                local idleStarCount = self.oldSubSegmentId_
                local starCount = self.newSubSegmentId_
                local animTime = 0
                for i = idleStarCount, 1, -1 do
                    local child = self.StarGroup.transform:GetChild(i - 1)
                    if i <= starCount then
                        CfUtils.PlayAnimation(child.gameObject, "LadderCompetionDanAnimStarDefault")
                    else
                        CfUtils.PlayAnimation(child.gameObject,"LadderCompetionDanAnimStarDrop")
                        animTime = CfUtils.GetAnimationTime(child.gameObject,"LadderCompetionDanAnimStarDrop")
                        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(animTime))
                        KTool.SetActive(child.gameObject,false)
                    end
                end
                lastAnimTime = CfUtils.GetAnimationTime(self.Root,"LadderCompetionDanAnimDropStar")
            end
        elseif self.segmentRiseStatus_ > 0 then -- 升段 星先掉再升
            local starCount = self.oldSubSegmentId_ --先把原来的星全都丢掉
            for i = 1, starCount do
                local child = self.StarGroup.transform:GetChild(i - 1) 
                CfUtils.PlayAnimation(child.gameObject,"LadderCompetionDanAnimStarDrop")
            end
            CfUtils.PlayAnimation(self.Root,"LadderCompetionDanAnimRise")
            local animTime = CfUtils.GetAnimationTime(self.Root, 'LadderCompetionDanAnimRise')
            coroutine.yield(CS.UnityEngine.WaitForSeconds(animTime))
            for i = 1, starCount do
                local child = self.StarGroup.transform:GetChild(i - 1)
                KTool.SetActive(child.gameObject,false)
            end
            local newStarCount = self.newSubSegmentId_
            for i = 1, newStarCount do
                local child = self.StarGroup.transform:GetChild(i - 1)
                KTool.SetActive(child.gameObject,true)
                CfUtils.PlayAnimation(child.gameObject,"LadderCompetionDanAnimStarRise")
                cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.05))
            end
        elseif self.segmentRiseStatus_ < 0 then --掉段 星先掉再掉
            local starCount = self.oldSubSegmentId_
            for i = 1, starCount do
                local child = self.StarGroup.transform:GetChild(i - 1)
                CfUtils.PlayAnimation(child.gameObject,"LadderCompetionDanAnimStarDrop")
            end
            CfUtils.PlayAnimation(self.Root,"LadderCompetionDanAnimDrop")
            local animTime = CfUtils.GetAnimationTime(self.Root, 'LadderCompetionDanAnimDrop')
            coroutine.yield(CS.UnityEngine.WaitForSeconds(animTime))

            local ladderCompetionUtils = import("Game.UI.LadderCompetion.LadderCompetionUtils")
            local subSegmentCount = ladderCompetionUtils.GetSubSegmentCount(self.newSegmentId_) or 1

            local newStarCount = self.newSubSegmentId_
            for i = 1, 5 do
                local child = self.StarGroup.transform:GetChild(i - 1)
                KTool.SetActive(child.gameObject,i <= subSegmentCount)
                CfUtils.PlayAnimation(child.gameObject, "LadderCompetionDanAnimStarDefault")
            end
            
            for i = subSegmentCount, newStarCount+1,-1 do
                local child = self.StarGroup.transform:GetChild(i - 1)
                CfUtils.PlayAnimation(child.gameObject,"LadderCompetionDanAnimStarDrop")
                animTime = CfUtils.GetAnimationTime(child.gameObject,"LadderCompetionDanAnimStarDrop")
                cs_coroutine.yield_return(Yielders.GetWaitForSeconds(animTime))
                KTool.SetActive(child.gameObject,false)
            end
        end
        coroutine.yield(CS.UnityEngine.WaitForSeconds(lastAnimTime))
        
        -- remove blocker
        UIRaycastBlocker:RemoveCondition(ANIM_ACTION_BLOCKER_NAME)

        -- finish callback
        if finishCB then finishCB() end
        
        self.animActionCo_ = nil
    end)
end


return LadderCompetionDanAnimDialog
